def build():
    out = []
    for r in F:
        (i, n, g, d, st, tier, age, town, cat, gim, say, fin, fdesc, move, sig, legend, target) = r
        w = worker(i, n, g, d, st, tier, age, town, cat, gim, say, fin, fdesc, legend=legend)
        add_moves([w], {i: move}, {i: sig})
        out.append(w)
    return out

if __name__ == "__main__":
    data = build()
    with open(OUT, "w") as f: json.dump(data, f, indent=1, ensure_ascii=False)
    with open(os.path.join(os.path.dirname(__file__), "..", "..", "docs", "parody", "targets-free-agents.md"), "w") as f:
        f.write("# Free agents and legends: who each one parodies (design reference, never shipped)\n\n" + "\n".join("- %s: %s" % (r[1], r[16]) for r in F) + "\n")
    print("wrote free_agents.json: %d people" % len(data))
